<?php
declare(strict_types=1); require_once __DIR__.'/_helper.php';
$errors=[];$tahunId=(int)($_POST['tahun_pelajaran_id']??$_GET['tahun_pelajaran_id']??0);$semesterId=(int)($_POST['semester_id']??$_GET['semester_id']??0);$jenisId=(int)($_POST['jenis_absensi_id']??0);$sholatId=(int)($_POST['jenis_sholat_id']??0);$tanggal=(string)($_POST['tanggal']??date('Y-m-d'));$nama=trim((string)($_POST['nama_sesi']??''));$mulai=(string)($_POST['jam_mulai']??'07:00');$selesai=(string)($_POST['jam_selesai']??'09:00');$terlambat=(string)($_POST['batas_terlambat']??'');
if($_SERVER['REQUEST_METHOD']==='POST'){require_valid_csrf();[$errors,$jenis]=absensi_session_validate($pdo,$tahunId,$semesterId,$jenisId,$sholatId?:null,$tanggal,$mulai,$selesai,$terlambat?:null,$nama);if(!$errors){$st=$pdo->prepare('INSERT INTO sesi_absensi (tahun_pelajaran_id,semester_id,jenis_absensi_id,jenis_sholat_id,tanggal,nama_sesi,jam_mulai,jam_selesai,batas_terlambat,status) VALUES (?,?,?,?,?,?,?,?,?,\'draft\')');$st->execute([$tahunId,$semesterId,$jenisId,$sholatId?:null,$tanggal,$nama,$mulai,$selesai,$terlambat?:null]);$id=(int)$pdo->lastInsertId();absensi_audit($pdo,'CREATE_SESSION',$id,'Membuat sesi '.$nama);redirect('absensi/detail.php?id='.$id.'&saved=1');}}
$tahun=$pdo->query('SELECT id,nama FROM tahun_pelajaran ORDER BY id DESC')->fetchAll();$semester=$pdo->query('SELECT id,tahun_pelajaran_id,nama FROM semester ORDER BY tahun_pelajaran_id DESC,id')->fetchAll();$jenis=$pdo->query("SELECT id,kode,nama,kategori FROM jenis_absensi WHERE aktif=1 ORDER BY urutan,id")->fetchAll();$sholat=$pdo->query("SELECT id,nama FROM jenis_sholat WHERE aktif=1 ORDER BY urutan,id")->fetchAll();
$page_title='Buat Sesi Absensi';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?><main class="main"><header class="topbar"><div class="topbar-title">Buat Sesi Absensi</div><div class="topbar-user"><?=e(user_name())?></div></header><section class="content attendance-detail-module"><div class="page-header"><div><h1>Buat Sesi Absensi</h1><p>Sesi baru dibuat sebagai <strong>Draft</strong>. Sesi harus diaktifkan sebelum scanner menerima scan.</p></div><a class="btn btn-secondary" href="<?=BASE_URL?>absensi/index.php">Kembali</a></div><?php foreach($errors as $x):?><div class="alert alert-danger"><?=e($x)?></div><?php endforeach;?><div class="form-card"><form method="post"><?=csrf_field()?><div class="form-grid"><label>Tahun Pelajaran *<select class="form-control" name="tahun_pelajaran_id" required><option value="">- Pilih -</option><?php foreach($tahun as $r):?><option value="<?=$r['id']?>" <?=$tahunId==(int)$r['id']?'selected':''?>><?=e($r['nama'])?></option><?php endforeach;?></select></label><label>Semester *<select class="form-control" name="semester_id" required><option value="">- Pilih -</option><?php foreach($semester as $r):?><option value="<?=$r['id']?>" data-tahun="<?=$r['tahun_pelajaran_id']?>" <?=$semesterId==(int)$r['id']?'selected':''?>><?=e($r['nama'])?></option><?php endforeach;?></select></label><label>Jenis Absensi *<select class="form-control" name="jenis_absensi_id" id="jenis_absensi_id" required><option value="">- Pilih -</option><?php foreach($jenis as $r):?><option value="<?=$r['id']?>" data-kategori="<?=e($r['kategori'])?>" <?=$jenisId==(int)$r['id']?'selected':''?>><?=e($r['nama'])?></option><?php endforeach;?></select></label><label id="sholat-wrap">Jenis Sholat<select class="form-control" name="jenis_sholat_id"><option value="">- Tidak ada -</option><?php foreach($sholat as $r):?><option value="<?=$r['id']?>" <?=$sholatId==(int)$r['id']?'selected':''?>><?=e($r['nama'])?></option><?php endforeach;?></select></label><label>Nama Sesi *<input class="form-control" name="nama_sesi" required value="<?=e($nama)?>" placeholder="Contoh: Absensi Masuk Pagi"></label><label>Tanggal *<input class="form-control" type="date" name="tanggal" required value="<?=e($tanggal)?>"></label><label>Jam Mulai *<input class="form-control time-24" type="text" inputmode="numeric" maxlength="5" name="jam_mulai" required value="<?=e($mulai)?>"></label><label>Jam Selesai *<input class="form-control time-24" type="text" inputmode="numeric" maxlength="5" name="jam_selesai" required value="<?=e($selesai)?>"></label><label>Batas Terlambat<input class="form-control time-24" type="text" inputmode="numeric" maxlength="5" name="batas_terlambat" value="<?=e($terlambat)?>"></label></div><div class="form-actions"><button class="btn btn-primary">Simpan Draft</button><a class="btn btn-secondary" href="<?=BASE_URL?>absensi/index.php">Batal</a></div></form></div><script src="<?=BASE_URL?>assets/js/time24.js"></script></section></main><script>const j=document.getElementById('jenis_absensi_id'),w=document.getElementById('sholat-wrap');function sync(){const o=j.options[j.selectedIndex];w.style.display=o&&o.dataset.kategori==='sholat'?'flex':'none';}j.addEventListener('change',sync);sync();</script><?php require_once __DIR__.'/../layouts/footer.php';?>
